/**
 * ASSET MANIFEST
 * --------------------------------------------------------------------------
 * Every piece of game art the app shows is listed here, and nowhere else.
 * Files live in /public/assets. All current art is PLACEHOLDER, generated by
 * scripts/generate-placeholders.mjs. To use your own illustrations:
 *   1. Overwrite a file in /public/assets with yours (same filename and size), or
 *   2. Add a new file and change its path + size below.
 * Then set `placeholder: false` so the "Placeholder" tag disappears.
 *
 * Pixel-art standards (docs/DESIGN_SYSTEM.md):
 *   map tiles 16×16 · environments 320×192 (20×12 tiles) · sprites 32×32 · portraits 96×96
 *   PNG with transparency, drawn at 1×. The app scales them up with nearest-neighbor.
 */
import type { EnvironmentTypeId, WorldId } from "@/lib/types";

export type ArtAsset = {
  src: string;
  /** Native pixel size of the art. The UI keeps this aspect ratio. */
  width: number;
  height: number;
  placeholder: boolean;
};

const ENV_SIZE = { width: 320, height: 192 };

export const titleArt: ArtAsset = { src: "/assets/ui/title-background.png", width: 320, height: 180, placeholder: true };

const WORLD_IDS: WorldId[] = ["western-fantasy", "modern", "ancient-china", "otherworld"];
const ENV_IDS: EnvironmentTypeId[] = ["interior", "street", "wilderness", "ruins", "dreamscape"];

/** One environment image per world × environment type. */
export const environmentArt = Object.fromEntries(
  WORLD_IDS.map((w) => [
    w,
    Object.fromEntries(ENV_IDS.map((e) => [e, { src: `/assets/environments/${w}/${e}.png`, ...ENV_SIZE, placeholder: true }])),
  ]),
) as Record<WorldId, Record<EnvironmentTypeId, ArtAsset>>;

/** World-select card art. Currently each world's most typical environment. */
export const worldArt: Record<WorldId, ArtAsset> = {
  "western-fantasy": environmentArt["western-fantasy"].wilderness,
  modern: environmentArt.modern.street,
  "ancient-china": environmentArt["ancient-china"].street,
  otherworld: environmentArt.otherworld.wilderness,
};

/** Fallback when no world is chosen yet. */
export const defaultWorld: WorldId = "otherworld";

/** Portrait (96×96) + in-game sprite (32×32) pairs. A character stores the index it uses. */
export const characterArt: { portrait: ArtAsset; sprite: ArtAsset }[] = [1, 2, 3, 4, 5, 6].map((n) => {
  const id = String(n).padStart(2, "0");
  return {
    portrait: { src: `/assets/characters/portrait-${id}.png`, width: 96, height: 96, placeholder: true },
    sprite: { src: `/assets/characters/sprite-${id}.png`, width: 32, height: 32, placeholder: true },
  };
});

export function getCharacterArt(index: number) {
  const len = characterArt.length;
  return characterArt[((index % len) + len) % len];
}
